import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        String text = new Scanner(System.in).next();
        Path utf8 = Path.of("utf8.txt");
        Path utf16 = Path.of("utf16le.txt");
        Files.writeString(utf8, text, StandardCharsets.UTF_8);
        Files.writeString(utf16, text, StandardCharsets.UTF_16LE);
        System.out.println("UTF8 " + Files.size(utf8));
        System.out.println("UTF16LE " + Files.size(utf16));
        System.out.println("TEXT "
                + Files.readString(utf8, StandardCharsets.UTF_8) + "|"
                + Files.readString(utf16, StandardCharsets.UTF_16LE));
    }
}

