import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Stream;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Path dir = Path.of("work", "incoming");
        Files.createDirectories(dir);
        try (Stream<Path> oldEntries = Files.list(dir)) {
            for (Path old : oldEntries.toList()) Files.deleteIfExists(old);
        }
        for (int i = 0; i < n; i++) {
            Files.writeString(dir.resolve(sc.next()), "");
        }
        List<String> names;
        try (Stream<Path> entries = Files.list(dir)) {
            names = entries
                    .filter(Files::isRegularFile)
                    .map(p -> p.getFileName().toString())
                    .filter(name -> name.endsWith(".txt"))
                    .sorted()
                    .toList();
        }
        System.out.println("TXT " + names.size()
                + (names.isEmpty() ? "" : " " + String.join(",", names)));
    }
}

