import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        String oldText = sc.next();
        String newText = sc.next();
        Path dir = Path.of("config");
        Path target = dir.resolve("settings.txt");
        Path temp = null;

        Files.createDirectories(dir);
        Files.writeString(target, oldText, StandardCharsets.UTF_8);
        try {
            temp = Files.createTempFile(dir, "settings-", ".tmp");
            Files.writeString(temp, newText, StandardCharsets.UTF_8);
            try {
                Files.move(temp, target,
                        StandardCopyOption.ATOMIC_MOVE,
                        StandardCopyOption.REPLACE_EXISTING);
            } catch (AtomicMoveNotSupportedException e) {
                Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
            }
        } finally {
            if (temp != null) Files.deleteIfExists(temp);
        }

        System.out.println("TARGET " + Files.readString(target, StandardCharsets.UTF_8));
        System.out.println("TEMP_EXISTS " + (temp != null && Files.exists(temp)));
        System.out.println("DIRECTORY " + Files.isDirectory(dir));
    }
}
